// ---------------------------------------------------------------------------------------------
// PATH_AND_QUERY
// ---------------------------------------------------------------------------------------------

// RFC 3986 unreserved characters, plus '/' in a path.
inline bool unreserved(const char* s, bool path) {
  if (s == nullptr) return true;
  for (; *s; s++) {
    const char c = *s;
    const bool alnum = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    if (alnum || c == '-' || c == '.' || c == '_' || c == '~' || (path && c == '/')) continue;
    return false;
  }
  return true;
}

// One query parameter as the server parsed it. `skip` for a POST body field or a file.
struct QueryParam {
  const char* name;
  const char* value;
  bool skip;
};

// PATH_AND_QUERY as sent. AsyncWebServer keeps only the percent-DECODED path and parsed parameters,
// not the request line, so the query is rebuilt from them in order as name=value joined by '&'.
// That is exact only when nothing was decoded, so a path or parameter outside RFC 3986's unreserved
// set (anything that needs %xx, or '+') is refused: false, and the request fails to verify.
// ePixC's clients send /json, /json/state, /json/cfg, /json/info and ?v=1-style queries only.
// A parameter sent with no '=' ("?flag") cannot be told from "?flag=" and is signed as the latter.
//
// `Str` is Arduino's String on the device and std::string in the tests; `get(i)` returns the i-th
// parameter as a QueryParam.
template <class Str, class GetParam>
bool buildPathAndQuery(Str& out, const char* path, size_t nParams, GetParam get) {
  if (path == nullptr || !unreserved(path, true)) return false;
  out = path;
  bool first = true;
  for (size_t i = 0; i < nParams; i++) {
    const QueryParam p = get(i);
    if (p.skip) continue;
    if (!unreserved(p.name, false) || !unreserved(p.value, false)) return false;
    out += first ? '?' : '&';
    first = false;
    out += p.name ? p.name : "";
    out += '=';
    out += p.value ? p.value : "";
  }
  return true;
}

// ---------------------------------------------------------------------------------------------
// /json/pixc/pair
// ---------------------------------------------------------------------------------------------

constexpr size_t kPairBodyMax = 1024;
constexpr size_t kDevKeyHexLen = 64;

// The hotspot's own subnet, 4.3.2.0/24, with lwIP's byte order (first octet lowest).
inline bool onHotspotSubnet(uint32_t ip) {
  return (ip & 0x00FFFFFFu) == (4u | (3u << 8) | (2u << 16));
}

inline bool pairBodySizeOk(size_t len) { return len > 0 && len <= kPairBodyMax; }

// A pairing body is stored only if every field is valid: SSID 1-32 bytes, a WPA2 key (8-63
// characters, 64 hex, or empty for an open network), K_dev 64 lowercase hex, K_lan 32 lowercase
// hex. Anything else is 400 and nothing is stored.
inline bool validPairBody(const char* ssid, const char* psk, const char* kDev, const char* kLan) {
  if (ssid == nullptr || psk == nullptr || kDev == nullptr || kLan == nullptr) return false;
  const size_t ssidLen = strlen(ssid);
  if (ssidLen == 0 || ssidLen > 32) return false;
  if (!validPsk(psk, strlen(psk))) return false;
  return isLowerHex(kDev, kDevKeyHexLen) && isLowerHex(kLan, kKeyHexLen);   // exact lengths
}

// A keyed light takes a new Wi-Fi password only from the phone that paired it: the same k_lan AND
// the same k_dev (the wrong-password retry). Anyone else - including a member or Sync, who hold
// k_lan but never k_dev - must factory-reset it first: true means 409 ALREADY_PAIRED. Both keys
// are compared in constant time. Call with a body validPairBody() accepted.
inline bool pairConflicts(bool keyed, const char* storedLan, const char* storedDev,
                          const char* kLan, const char* kDev) {
  if (!keyed) return false;
  const bool lanOk = equalConstTime(storedLan, kLan, kKeyHexLen);
  const bool devOk = equalConstTime(storedDev, kDev, kDevKeyHexLen);
  return !(lanOk && devOk);
}

// ---------------------------------------------------------------------------------------------
// Realtime (DDP) leases
// ---------------------------------------------------------------------------------------------

// Who may send DDP: an address that holds a lease from an authenticated POST /json
// {"pixc":{"rt_lease":N}}. Times are millis(), compared by unsigned difference so the wrap at
// ~49.7 days neither expires nor extends a lease.
class LeaseTable {
 public:
  static constexpr uint8_t kSlots = 4;
  static constexpr uint16_t kMaxS = 120;

  // Grant `ip` a lease of `wantS` seconds (capped at kMaxS), or release it with wantS <= 0. The
  // caller gets its own slot, else a free or expired one, else the one ending soonest.
  void grant(uint32_t ip, int wantS, uint32_t now) {
    if (ip == 0) return;
    const uint16_t secs = wantS <= 0 ? 0 : (wantS > kMaxS ? kMaxS : static_cast<uint16_t>(wantS));
    uint8_t slot = 0;
    for (uint8_t i = 0; i < kSlots; i++) {
      if (_l[i].ip == ip) { slot = i; break; }
      if (_l[i].ip == 0 || !live(i, now)) slot = i;
      else if (_l[slot].ip != 0 && live(slot, now) &&
               static_cast<int32_t>(_l[i].until - _l[slot].until) < 0) slot = i;
    }
    if (secs == 0) { if (_l[slot].ip == ip) _l[slot].ip = 0; return; }
    _l[slot].ip = ip;
    _l[slot].until = now + secs * 1000u;
  }

  bool allowed(uint32_t ip, uint32_t now) const {
    if (ip == 0) return false;
    for (uint8_t i = 0; i < kSlots; i++) if (_l[i].ip == ip && live(i, now)) return true;
    return false;
  }

 private:
  bool live(uint8_t i, uint32_t now) const { return static_cast<int32_t>(now - _l[i].until) < 0; }
  struct Lease { uint32_t ip; uint32_t until; };
  Lease _l[kSlots] = {};
};

// ---------------------------------------------------------------------------------------------
// LAN /json/cfg writes
// ---------------------------------------------------------------------------------------------

// Remove what a LAN config write may not change: every network interface setting ("if": the
// broker, the UDP sync notifier, realtime input, NTP, node list), the access point, OTA settings,
// the settings PIN, ePixC's own section, the usermod's provisioning keys, and any button, relay or
// IR receiver. The keys are written only at pairing and by the cloud. `Obj` is ArduinoJson's
// JsonObject.
//
// All of "if", not only "if.mqtt" (security audit 2026-10-20): no ePixC client writes it (the app
// writes nw, hw.led and um.AudioReactive; Sync writes no config), and "if.sync.recv.grp" or
// "if.sync.send.en" switch on WLED's sync notifier, which carries no credential. A member could
// switch it on before being removed and then, after the key rotation, still drive the light from
// any host on the LAN with plain UDP packets.
template <class Obj>
void sanitizeLanCfg(Obj root) {
  root.remove("if");
  root.remove("ap");
  root.remove("ota");
  root.remove("pin");
  root.remove("pixc");
  Obj um = root["um"];
  if (!um.isNull()) um.remove("PixcConnect");
  // No button, relay or IR receiver is fitted (BTNPIN, RLYPIN and IRPIN are -1), and a LAN write
  // must not add one. WLED formats the filesystem when button 0 is released after a 10 s hold
  // (button.cpp), and a touch button whose threshold (hw.btn.tt) is moved by a second write can be
  // held and "released" on demand: a LAN factory reset for anyone holding the LAN key, which pairing
  // v2 rules out (vault: "No LAN reset"). The app writes hw.led only.
  Obj hw = root["hw"];
  if (!hw.isNull()) {
    hw.remove("btn");
    hw.remove("relay");
    hw.remove("ir");
  }
}

// ---------------------------------------------------------------------------------------------
// State writes (signed LAN, MQTT …/api, presets)
// ---------------------------------------------------------------------------------------------

// Remove what a state write may not do, whoever sent it (security audit 2026-10-20). Called at the
// top of deserializeState() and on a preset before it is applied; `fromPreset` is true for a stored
// preset (boot preset, timer, playlist), false for a request.
//  - "win": WLED's HTTP-style API inside JSON. It reaches handleSet() (RN=/SN= switch the UDP sync
//    notifier on, RD= realtime input off, RB reboots), which ePixC removed from the LAN, UDP and
//    MQTT. No ePixC client sends it.
//  - "udpn" send, sgrp, rgrp: the same notifier switches in JSON. "nn" (do not notify) stays.
//  - "rb" from a stored preset: a preset {"rb":true} saved as the boot preset reboots the light
//    about a second into every boot. A software reboot is not a crash, so WLED's boot-loop handler
//    never steps in, and the five-power-on reset never counts a power-on that short: the light
//    would need a cable. A request may still reboot the light; a preset may not.
//  - "psave", "pdel" and "rmcpal" from a stored preset (D465): each is a filesystem write, and a
//    playlist of presets that save or delete presets, or remove a palette file, writes flash at
//    every step, for ever, after one request - past the write ceiling below, which counts requests.
//    WLED drops "psave" from a stored API preset already; "pdel" and "rmcpal" it kept.
template <class Obj>
void sanitizeState(Obj root, bool fromPreset) {
  root.remove("win");
  Obj udpn = root["udpn"];
  if (!udpn.isNull()) {
    udpn.remove("send");
    udpn.remove("sgrp");
    udpn.remove("rgrp");
  }
  if (fromPreset) {
    root.remove("rb");
    root.remove("psave");
    root.remove("pdel");
    root.remove("rmcpal");
  }
}

// ---------------------------------------------------------------------------------------------
// Flash writes caused by signed requests (D465)
// ---------------------------------------------------------------------------------------------
// A token bucket of filesystem writes: `burst` at once, then one every `refillMs`. Time is passed
// in (milliseconds, 64-bit, so no wrap), like PinGuard, so the host tests drive it. A full bucket
// does not bank time. One instance per task: it holds no lock.
class WriteBudget {
 public:
  WriteBudget(uint8_t burst, uint32_t refillMs) : _burst(burst), _refillMs(refillMs), _tokens(burst) {}

  // Spend one write now if there is one. When there is none, `waitMs` (if given) says how long
  // until there will be, for a Retry-After; it is 0 on success.
  bool take(uint64_t now, uint64_t* waitMs = nullptr) {
    tick(now);
    if (_tokens > 0) {
      _tokens--;
      if (waitMs != nullptr) *waitMs = 0;
      return true;
    }
    if (waitMs != nullptr) *waitMs = _refillMs - (now - _lastRefill);
    return false;
  }
  uint8_t tokens(uint64_t now) { tick(now); return _tokens; }

 private:
  void tick(uint64_t now) {
    if (!_started) { _started = true; _lastRefill = now; }
    if (now < _lastRefill) _lastRefill = now;          // a clock that went back banks nothing
    while (_tokens < _burst && now - _lastRefill >= _refillMs) {
      _tokens++;
      _lastRefill += _refillMs;
    }
    if (_tokens == _burst) _lastRefill = now;
  }
  uint8_t _burst;
  uint32_t _refillMs;
  uint8_t _tokens;
  uint64_t _lastRefill = 0;
  bool _started = false;
};

// cfg.json (with wsec.json and the backup copy WLED writes beside it): three at once, then one
// every 30 s. Applied where WLED::loop() saves for configNeedsWrite, so it holds for every path that
// sets the flag - a signed /json/cfg, the bus re-init that a LED change causes, a cloud fragment, a
// pairing. A write that has to wait is not dropped: the flag stays set, the next token saves the
// configuration as it is then (every change made meanwhile, in one write), and WLED::reset()
// saves a pending one before any reboot. The change itself is live in RAM at once; only the copy
// on flash waits, so a person changing settings sees nothing. What a power cut can lose is the
// last 30 s of changes made faster than that.
constexpr uint8_t kCfgWriteBurst = 3;
constexpr uint32_t kCfgWriteRefillMs = 30000;
// presets.json and palette files from a signed state write ("psave", "pdel", "rmcpal"): five at
// once, then one every 30 s. A write over the budget is refused whole with a signed 429 and a
// Retry-After before any of it is applied - a preset cannot be saved later on the sender's behalf
// (WLED saves one at a time from the live state), and refusing tells the sender instead of losing
// it quietly. No ePixC client saves or deletes presets on the light (the app keeps them in the
// cloud); the budget is a ceiling on a hostile or broken key holder, not a limit people meet.
constexpr uint8_t kPresetWriteBurst = 5;
constexpr uint32_t kPresetWriteRefillMs = 30000;

// Does this state write touch the filesystem? The same conversions and ranges as WLED's
// deserializeState(): "psave" and "pdel" 1-250 (255, the temporary preset, stays in RAM on an
// ESP32), and "rmcpal" whenever present (it removes /paletteN.json).
template <class Obj>
bool persistsState(Obj root) {
  const uint8_t save = root["psave"].template as<uint8_t>();
  const uint8_t del = root["pdel"].template as<uint8_t>();
  if (save > 0 && save < 251) return true;
  if (del > 0 && del < 251) return true;
  return root.containsKey("rmcpal");
}

// ---------------------------------------------------------------------------------------------
// Request bodies, decided from the headers (D465)
// ---------------------------------------------------------------------------------------------
// AsyncWebServer picks a handler when the headers end and only then reads the body: the JSON
// handler copies it whole (up to 16 KB) into the heap, and any handler with a callback parses a
// form or text/plain body into String parameters, with no limit at all. pixc_lan.cpp registers a
// gate first, which takes - and reads nothing of the body of - a request this classifies as:
//   Discard      a body WLED would parse into parameters (form, text/plain, multipart). No route a
//                release image serves reads them: the JSON API and pairing take JSON only. The
//                reply is the not-found handler's 404.
//   SignedWrite  a JSON write the signed /json handler would buffer. The gate runs the checks that
//                need no body (rate limit, a keyed light, the header's shape, the boot id) and
//                takes the request only if they fail, with the reply pixcPreAuthorise() gives.
//   Normal       everything else: no body, a body nothing buffers, the pairing POST (hotspot only,
//                1 KB), or a JSON body of 16 KB or more, which the JSON handler never copies (413).
// The signature over the body is still checked where it always was, after the body.
enum class BodyRoute : uint8_t { Normal, SignedWrite, Discard };
constexpr size_t kJsonBodyMax = 16384;   // AsyncCallbackJsonWebHandler's default _maxContentLength

inline bool asciiEqualNoCase(const char* a, const char* b) {
  for (; *a && *b; a++, b++) {
    char x = *a, y = *b;
    if (x >= 'A' && x <= 'Z') x = static_cast<char>(x - 'A' + 'a');
    if (y >= 'A' && y <= 'Z') y = static_cast<char>(y - 'A' + 'a');
    if (x != y) return false;
  }
  return *a == *b;
}

// `contentType` as AsyncWebServer keeps it (the header up to any ';'); `writeMethod` is POST, PUT
// or PATCH; `multipart` is the server's own flag ("multipart/..." content type).
inline BodyRoute classifyBody(bool writeMethod, const char* url, const char* contentType,
                              size_t contentLength, bool multipart) {
  if (contentLength == 0 || url == nullptr) return BodyRoute::Normal;
  const char* ct = contentType ? contentType : "";
  // The same tests WebRequest.cpp makes before it parses a body into parameters (its text/plain
  // test also looks at the first body byte, which is not here yet: every text/plain body counts).
  if (multipart || strncmp(ct, "application/x-www-form-urlencoded", 33) == 0 || strcmp(ct, "text/plain") == 0)
    return BodyRoute::Discard;
  const bool jsonPath = strcmp(url, "/json") == 0 || strncmp(url, "/json/", 6) == 0;
  const bool pairPath = strcmp(url, "/json/pixc/pair") == 0 || strncmp(url, "/json/pixc/pair/", 16) == 0;
  if (!writeMethod || !jsonPath || pairPath || !asciiEqualNoCase(ct, "application/json") ||
      contentLength >= kJsonBodyMax)
    return BodyRoute::Normal;
  return BodyRoute::SignedWrite;
}

